# ============================================================
# COOKIE VALIDATION
# ============================================================

def validate_cookie(cookie):
    if not isinstance(cookie, dict):
        return False, "Cookie entry must be an object."

    if "name" not in cookie:
        return False, "Missing cookie name."

    if "value" not in cookie:
        return False, "Missing cookie value."

    name = cookie["name"]

    if not isinstance(name, str) or not name.strip():
        return False, "Cookie name must be a non-empty string."

    value = cookie["value"]
    if not isinstance(value, str):
        value = str(value)

    cleaned = {
        "name": name.strip(),
        "value": value
    }

    if "domain" in cookie:
        domain = cookie["domain"]

        if not isinstance(domain, str) or not domain.strip():
            return False, f"Invalid domain for '{name}'."

        cleaned["domain"] = domain.strip()

    if "path" in cookie:
        path = cookie["path"]

        if not isinstance(path, str) or not path.startswith("/"):
            return False, f"Invalid path for '{name}'."

        cleaned["path"] = path

    if "secure" in cookie:
        if not isinstance(cookie["secure"], bool):
            return False, f"'secure' must be true/false for '{name}'."

        cleaned["secure"] = cookie["secure"]

    if "expiry" in cookie:
        try:
            expiry = int(cookie["expiry"])

            if expiry > 0:
                cleaned["expiry"] = expiry

        except (ValueError, TypeError):
            return False, f"Invalid expiry for '{name}'."

    if "sameSite" in cookie:
        same_site = cookie["sameSite"]

        if same_site not in ("Strict", "Lax", "None"):
            return False, (
                f"Invalid sameSite value for '{name}'."
            )

        cleaned["sameSite"] = same_site

    return True, cleaned


def parse_cookie_data(raw):
    """
    Supports:
      - JSON cookie arrays/objects
      - Netscape cookies.txt
      - HTTP Cookie header
    """

    raw = raw.strip()

    if not raw:
        return [], ["Input is empty."]

    cookies = []
    errors = []

    # --------------------------------------------------------
    # JSON
    # --------------------------------------------------------

    if raw.startswith("[") or raw.startswith("{"):
        try:
            data = json.loads(raw)

            if isinstance(data, dict):
                items = [data]
            elif isinstance(data, list):
                items = data
            else:
                return [], ["JSON must contain an object or array."]

            for number, item in enumerate(items, 1):
                valid, result = validate_cookie(item)

                if valid:
                    cookies.append(result)
                else:
                    errors.append(
                        f"JSON entry #{number}: {result}"
                    )

            if cookies:
                return cookies, errors

        except json.JSONDecodeError as exc:
            errors.append(f"Invalid JSON: {exc}")

    # --------------------------------------------------------
    # Netscape cookies.txt
    # --------------------------------------------------------

    for line_number, line in enumerate(raw.splitlines(), 1):
        line = line.strip()

        if not line or line.startswith("#"):
            continue

        parts = line.split("\t")

        if len(parts) < 7:
            parts = line.split()

        if len(parts) >= 7:
            try:
                cookie = {
                    "domain": parts[0],
                    "path": parts[2],
                    "secure": parts[3].upper() == "TRUE",
                    "name": parts[5],
                    "value": parts[6]
                }

                try:
                    expiry = int(parts[4])

                    if expiry > 0:
                        cookie["expiry"] = expiry

                except ValueError:
                    pass

                valid, result = validate_cookie(cookie)

                if valid:
                    cookies.append(result)
                else:
                    errors.append(
                        f"cookies.txt line {line_number}: {result}"
                    )

            except Exception as exc:
                errors.append(
                    f"cookies.txt line {line_number}: {exc}"
                )

    if cookies:
        return cookies, errors

    # --------------------------------------------------------
    # HTTP Cookie header
    # --------------------------------------------------------

    try:
        parser = SimpleCookie()
        parser.load(raw)

        for name, morsel in parser.items():
            cookie = {
                "name": name,
                "value": morsel.value
            }

            valid, result = validate_cookie(cookie)

            if valid:
                cookies.append(result)
            else:
                errors.append(result)

    except Exception as exc:
        errors.append(
            f"Cookie header parsing failed: {exc}"
        )

    return cookies, errors


# ============================================================
# URL VALIDATION
# ============================================================

def validate_url(url):
    url = url.strip()

    if not url:
        return False, "URL is empty."

    if not re.match(r"^https?://", url, re.IGNORECASE):
        return False, "URL must start with http:// or https://"

    try:
        parsed = urlparse(url)

        if not parsed.hostname:
            return False, "A valid hostname is required."

        if " " in parsed.netloc:
            return False, "The hostname cannot contain spaces."

        return True, url

    except Exception as exc:
        return False, f"URL parsing failed: {exc}"


# ============================================================
# GUI
# ============================================================

class SessionForgeV3:

    def __init__(self, root):
        self.root = root
        self.root.title(f"{APP_NAME} {VERSION}")
        self.root.geometry("820x900")
        self.root.minsize(720, 760)
        self.root.configure(bg=BG)

        self.logo_photo = None
        self.validated_cookies = []
        self.validation_errors = []

        self.build_ui()
        self.bind_shortcuts()

    # --------------------------------------------------------
    # UI BUILD
    # --------------------------------------------------------

    def build_ui(self):

        # Top bar
        top = tk.Frame(self.root, bg=BG)
        top.pack(fill="x", padx=26, pady=(18, 5))

        tk.Label(
            top,
            text="X-CORE",
            font=("Arial", 10, "bold"),
            fg=ACCENT,
            bg=BG
        ).pack(side="left")

        tk.Label(
            top,
            text=f"SESSIONFORGE  {VERSION}",
            font=("Arial", 9),
            fg=MUTED,
            bg=BG
        ).pack(side="left", padx=10)

        tk.Button(
            top,
            text="ABOUT",
            command=self.show_about,
            font=("Arial", 8, "bold"),
            bg=BG,
            fg=MUTED,
            activebackground=BG,
            activeforeground=TEXT,
            relief="flat",
            bd=0,
            cursor="hand2"
        ).pack(side="right")

        # Logo
        logo_area = tk.Frame(self.root, bg=BG)
        logo_area.pack(fill="x", pady=(0, 8))

        self.load_logo(logo_area)

        tk.Label(
            logo_area,
            text="AUTHORIZED SESSION TESTING CONSOLE",
            font=("Arial", 9, "bold"),
            fg=ACCENT,
            bg=BG
        ).pack(pady=(4, 0))

        # Main panel
        panel = tk.Frame(
            self.root,
            bg=PANEL,
            highlightbackground=BORDER,
            highlightthickness=1
        )
        panel.pack(
            fill="both",
            expand=True,
            padx=28,
            pady=12
        )

        # Target
        self.section_label(panel, "01  TARGET WEBSITE")

        url_row = tk.Frame(panel, bg=PANEL)
        url_row.pack(fill="x", padx=24, pady=(2, 18))

        self.url_entry = tk.Entry(
            url_row,
            font=("Arial", 12),
            bg=FIELD,
            fg=TEXT,
            insertbackground=TEXT,
            relief="flat",
            highlightbackground=BORDER,
            highlightcolor=ACCENT,
            highlightthickness=1
        )
        self.url_entry.pack(
            side="left",
            fill="x",
            expand=True,
            ipady=9
        )
        self.url_entry.insert(0, "https://")

        # URL status
        self.url_indicator = tk.Label(
            url_row,
            text=" ●",
            font=("Arial", 12, "bold"),
            fg=MUTED,
            bg=FIELD
        )
        self.url_indicator.place(
            relx=0.975,
            rely=0.5,
            anchor="e"
        )

        # Cookie section
        self.section_label(panel, "02  SESSION DATA")

        cookie_hint = tk.Frame(panel, bg=PANEL)
        cookie_hint.pack(fill="x", padx=24, pady=(0, 6))

        tk.Label(
            cookie_hint,
            text="JSON  •  cookies.txt  •  HTTP Cookie header",
            font=("Arial", 9),
            fg=MUTED,
            bg=PANEL
        ).pack(side="left")

        self.count_label = tk.Label(
            cookie_hint,
            text="0 entries",
            font=("Arial", 9, "bold"),
            fg=MUTED,
            bg=PANEL
        )
        self.count_label.pack(side="right")

        self.cookie_box = scrolledtext.ScrolledText(
            panel,
            height=14,
            font=("Consolas", 10),
            bg=FIELD,
            fg=TEXT,
            insertbackground=TEXT,
            selectbackground=ACCENT_DARK,
            relief="flat",
            wrap=tk.WORD,
            highlightbackground=BORDER,
            highlightcolor=ACCENT,
            highlightthickness=1
        )
        self.cookie_box.pack(
            fill="both",
            expand=True,
            padx=24,
            pady=(0, 7)
        )

        self.cookie_box.bind(
            "<KeyRelease>",
            self.on_cookie_change
        )

        # Cookie actions
        actions = tk.Frame(panel, bg=PANEL)
        actions.pack(fill="x", padx=24, pady=(0, 18))

        self.small_button(
            actions,
            "CLEAR",
            self.clear_cookies
        ).pack(side="left")

        self.small_button(
            actions,
            "PASTE",
            self.paste_cookies
        ).pack(side="left", padx=6)

        self.small_button(
            actions,
            "VALIDATE",
            self.validate_inputs,
            accent=True
        ).pack(side="right")

        # Status
        self.section_label(panel, "03  VALIDATION STATUS")

        status = tk.Frame(
            panel,
            bg=PANEL_2,
            highlightbackground=BORDER,
            highlightthickness=1
        )
        status.pack(fill="x", padx=24, pady=(2, 8))

        self.status_dot = tk.Label(
            status,
            text="●",
            font=("Arial", 15, "bold"),
            fg=MUTED,
            bg=PANEL_2
        )
        self.status_dot.pack(
            side="left",
            padx=(14, 8),
            pady=13
        )

        status_text = tk.Frame(status, bg=PANEL_2)
        status_text.pack(
            side="left",
            fill="x",
            expand=True,
            pady=10
        )

        self.status_label = tk.Label(
            status_text,
            text="Ready for validation.",
            font=("Arial", 10, "bold"),
            fg=MUTED,
            bg=PANEL_2,
            anchor="w"
        )
        self.status_label.pack(fill="x")

        self.status_detail = tk.Label(
            status_text,
            text="No session data has been validated.",
            font=("Arial", 8),
            fg="#657483",
            bg=PANEL_2,
            anchor="w"
        )
        self.status_detail.pack(fill="x", pady=(2, 0))

        # Bottom launch
        bottom = tk.Frame(panel, bg=PANEL)
        bottom.pack(fill="x", padx=24, pady=(8, 22))

        self.launch_button = tk.Button(
            bottom,
            text="LAUNCH BROWSER   ›",
            command=self.launch_browser,
            font=("Arial", 11, "bold"),
            bg=ACCENT,
            fg="white",
            activebackground=ACCENT_HOVER,
            activeforeground="white",
            relief="flat",
            bd=0,
            padx=30,
            pady=13,
            cursor="hand2"
        )
        self.launch_button.pack(side="right")

        # Footer
        footer = tk.Frame(self.root, bg=BG)
        footer.pack(fill="x", padx=30, pady=(0, 10))

        tk.Label(
            footer,
            text="LOCAL VALIDATION",
            font=("Arial", 8, "bold"),
            fg=SUCCESS,
            bg=BG
        ).pack(side="left")

        tk.Label(
            footer,
            text="X-core SessionForge",
            font=("Arial", 8),
            fg="#5d6b78",
            bg=BG
        ).pack(side="right")

    # --------------------------------------------------------
    # COMPONENT HELPERS
    # --------------------------------------------------------

    def load_logo(self, parent):
        if Image and ImageTk:
            try:
                from io import BytesIO

                image_bytes = base64.b64decode(LOGO_DATA)
                image = Image.open(BytesIO(image_bytes)).convert("RGBA")
                image.thumbnail((430, 250), Image.Resampling.LANCZOS)
                self.logo_photo = ImageTk.PhotoImage(image)

                tk.Label(
                    parent,
                    image=self.logo_photo,
                    bg=BG
                ).pack()

                return

            except Exception:
                pass

        # Text fallback if Pillow/image decoding is unavailable.
        tk.Label(
            parent,
            text="X",
            font=("Arial", 50, "bold"),
            fg=ACCENT,
            bg=BG
        ).pack()

        tk.Label(
            parent,
            text="X-CORE",
            font=("Arial", 25, "bold"),
            fg=TEXT,
            bg=BG
        ).pack()

    def section_label(self, parent, text):
        tk.Label(
            parent,
            text=text,
            font=("Arial", 10, "bold"),
            fg=TEXT,
            bg=PANEL,
            anchor="w"
        ).pack(fill="x", padx=24, pady=(18, 4))

    def small_button(self, parent, text, command, accent=False):
        return tk.Button(
            parent,
            text=text,
            command=command,
            font=("Arial", 8, "bold"),
            bg=ACCENT if accent else "#162331",
            fg="white" if accent else MUTED,
            activebackground=ACCENT_HOVER if accent else "#203346",
            activeforeground="white",
            relief="flat",
            bd=0,
            padx=14,
            pady=7,
            cursor="hand2"
        )

    # --------------------------------------------------------
    # EVENTS
    # --------------------------------------------------------

    def bind_shortcuts(self):
        self.root.bind(
            "<Control-Return>",
            lambda event: self.validate_inputs()
        )

        self.root.bind(
            "<Control-l>",
            lambda event: self.url_entry.focus_set()
        )

    def on_cookie_change(self, event=None):
        raw = self.cookie_box.get("1.0", tk.END).strip()

        if not raw:
            self.count_label.configure(
                text="0 entries",
                fg=MUTED
            )
            return

        cookies, errors = parse_cookie_data(raw)

        self.count_label.configure(
            text=f"{len(cookies)} valid",
            fg=SUCCESS if cookies else WARNING
        )

    # --------------------------------------------------------
    # ACTIONS
    # --------------------------------------------------------

    def clear_cookies(self):
        self.cookie_box.delete("1.0", tk.END)
        self.validated_cookies = []
        self.validation_errors = []

        self.count_label.configure(
            text="0 entries",
            fg=MUTED
        )

        self.set_status(
            "Session data cleared.",
            "normal",
            "Paste authorized test data and run validation."
        )

    def paste_cookies(self):
        try:
            clipboard = self.root.clipboard_get()

            if clipboard:
                self.cookie_box.delete("1.0", tk.END)
                self.cookie_box.insert("1.0", clipboard)
                self.on_cookie_change()

                self.set_status(
                    "Clipboard data loaded.",
                    "normal",
                    "Run validation to inspect the supplied format."
                )

        except tk.TclError:
            messagebox.showwarning(
                "Clipboard",
                "No text data was available on the clipboard."
            )

    def validate_inputs(self):

        url = self.url_entry.get().strip()
        raw = self.cookie_box.get("1.0", tk.END).strip()

        valid_url, url_result = validate_url(url)

        if not valid_url:
            self.url_indicator.configure(fg=ERROR)

            self.set_status(
                "URL validation failed.",
                "error",
                url_result
            )

            messagebox.showerror(
                "Invalid URL",
                url_result
            )
            return False

        self.url_indicator.configure(fg=SUCCESS)

        if not raw:
            self.set_status(
                "No session data supplied.",
                "warning",
                "The cookie input field is empty."
            )

            messagebox.showwarning(
                "Missing Session Data",
                "Paste cookie data before validation."
            )
            return False

        cookies, errors = parse_cookie_data(raw)

        self.validated_cookies = cookies
        self.validation_errors = errors

        if not cookies:
            self.count_label.configure(
                text="0 valid",
                fg=ERROR
            )

            self.set_status(
                "Validation failed.",
                "error",
                "No valid cookie entries were detected."
            )

            detail = "\n".join(errors[:8])

            messagebox.showerror(
                "Validation Failed",
                detail or "No valid entries were found."
            )

            return False

        self.count_label.configure(
            text=f"{len(cookies)} valid",
            fg=SUCCESS
        )

        if errors:
            self.set_status(
                "Validation completed with warnings.",
                "warning",
                f"{len(cookies)} valid • {len(errors)} skipped"
            )

            messagebox.showwarning(
                "Validation Complete",
                f"{len(cookies)} valid entries detected.\n"
                f"{len(errors)} invalid entries skipped."
            )

        else:
            self.set_status(
                "Validation successful.",
                "success",
                f"{len(cookies)} valid cookie entries detected."
            )

            messagebox.showinfo(
                "Validation Complete",
                f"{len(cookies)} valid cookie entries detected."
            )

        return True

    def launch_browser(self):

        url = self.url_entry.get().strip()

        valid_url, url_result = validate_url(url)

        if not valid_url:
            self.url_indicator.configure(fg=ERROR)

            self.set_status(
                "Cannot launch browser.",
                "error",
                url_result
            )

            messagebox.showerror(
                "Invalid URL",
                url_result
            )
            return

        if not self.validated_cookies:
            if not self.validate_inputs():
                return

        try:
            webbrowser.open_new_tab(url)

            self.set_status(
                "Browser launched.",
                "success",
                "Validated session data remains local to this application."
            )

        except Exception as exc:
            self.set_status(
                "Browser launch failed.",
                "error",
                str(exc)
            )

            messagebox.showerror(
                "Browser Error",
                str(exc)
            )

    # --------------------------------------------------------
    # STATUS
    # --------------------------------------------------------

    def set_status(self, title, state="normal", detail=""):

        colors = {
            "normal": MUTED,
            "success": SUCCESS,
            "warning": WARNING,
            "error": ERROR
        }

        color = colors.get(state, MUTED)

        self.status_dot.configure(fg=color)
        self.status_label.configure(
            text=title,
            fg=color
        )

        self.status_detail.configure(
            text=detail
        )

    def show_about(self):

        messagebox.showinfo(
            f"{APP_NAME} {VERSION}",
            "X-core SessionForge\n\n"
            "Version 3.0\n"
            "Dark X-core interface\n"
            "Local cookie/session-data validation\n"
            "URL validation\n"
            "JSON / cookies.txt / HTTP header parsing\n\n"
            "Designed for authorized testing and development."
        )


def main():

    root = tk.Tk()

    try:
        root.tk.call("tk", "scaling", 1.12)
    except tk.TclError:
        pass

    SessionForgeV3(root)

    root.mainloop()


if __name__ == "__main__":
    main()
